#!/usr/bin/env bash
set -Eeuo pipefail

STAGE_VERSION="rnatr_general_repeat_caller_bootstrap_v0.1.1"
PROJECT_ROOT="/mnt/intelssd/rnatr_project"
SSOT_CLI="$PROJECT_ROOT/metadata/ssot/rnatr_ssot.py"
SSOT_DB="$PROJECT_ROOT/metadata/ssot/rnatr_ssot.sqlite"
STAGE6AM_QC="$PROJECT_ROOT/qc/11_six_sample_frozen_p01_replay/ENCSR307SHM_pilot100k_mm2splice_v1/rnatr_six_sample_frozen_p01_replay_v0.1.5/six_sample_frozen_p01_replay.qc.tsv"
TARGET_EVIDENCE="$PROJECT_ROOT/results/11_periodic_calibrated/ENCSR307SHM_pilot100k_mm2splice_v1/v0.3.3/simple_periodic_evidence.calibrated.v0.3.3.tsv.gz"
CONTRACT="$PROJECT_ROOT/docs/design/RNA_TR_Scout_general_repeat_caller_contract_v0.1.0.md"
CALLER_DIR="$PROJECT_ROOT/src/rnatr_scout/general_caller"
CALLER="$CALLER_DIR/rnatr_general_repeat_caller_ref_v0.1.0.py"
BENCH="$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.1.0"
SELFTEST="$BENCH/rnatr_general_repeat_caller_fixture_selftest_v0.1.0.py"
QC_DIR="$PROJECT_ROOT/qc/12_general_repeat_caller_bootstrap/v0.1.0"
QC="$QC_DIR/general_repeat_caller_bootstrap.qc.tsv"
SCRIPT_INSTALL="$PROJECT_ROOT/scripts/12a_bootstrap_general_repeat_caller_v0.1.1.sh"

for p in "$SSOT_CLI" "$SSOT_DB" "$STAGE6AM_QC" "$TARGET_EVIDENCE"; do
  [[ -s "$p" ]] || { echo "ERROR: required input missing: $p" >&2; exit 2; }
done
stage6am_status="$(awk -F '\t' '$1=="stage6am_status"{print $2}' "$STAGE6AM_QC")"
[[ "$stage6am_status" == "PASS_SIX_SAMPLE_FROZEN_P01_REPLAY_COMPLETE" ]] || {
  echo "ERROR: Stage 6AM not complete: $stage6am_status" >&2; exit 2;
}

echo "===== SSOT STRUCTURAL PREFLIGHT ====="
python - "$SSOT_CLI" <<'PYSSOTPREFLIGHT'
from pathlib import Path
import re,sys
cli=Path(sys.argv[1]); text=cli.read_text(encoding='utf-8')
m=re.search(r'(?m)^TOOL_VERSION\s*=\s*["\']([^"\']+)["\']\s*$', text)
if not m:
    raise SystemExit('ERROR: SSOT TOOL_VERSION declaration not found')
required=[
    'def add_decision(', 'def add_interpretation(', 'def add_contract(',
    'CREATE TABLE open_questions', 'CREATE TABLE limitations',
    '    current_metrics = [\n'
]
missing=[x for x in required if x not in text]
if missing:
    raise SystemExit('ERROR: SSOT structural contract missing: '+', '.join(missing))
if text.count('    current_metrics = [\n') != 1:
    raise SystemExit('ERROR: SSOT current_metrics anchor is not unique')
if '# Stage 12A general caller bootstrap v0.1.0' in text:
    raise SystemExit('ERROR: Stage 12A SSOT patch marker already present; inspect existing state before rerun')
print('SSOT_STRUCTURAL_PREFLIGHT_PASS')
print('tool_version\t'+m.group(1))
PYSSOTPREFLIGHT

for p in "$CONTRACT" "$CALLER" "$SELFTEST" "$QC" "$BENCH" "$QC_DIR"; do
  [[ ! -e "$p" ]] || { echo "ERROR: refusing overwrite: $p" >&2; exit 2; }
done
mkdir -p "$(dirname "$CONTRACT")" "$CALLER_DIR" "$BENCH" "$QC_DIR"

CLI_BAK=""
DB_BAK=""
cleanup_fail() {
  rc=$?
  echo "ERROR: Stage 12A failed; cleaning newly created Stage 12A files" >&2
  if [[ -n "$CLI_BAK" && -f "$CLI_BAK" ]]; then cp -a "$CLI_BAK" "$SSOT_CLI"; fi
  if [[ -n "$DB_BAK" && -f "$DB_BAK" ]]; then cp -a "$DB_BAK" "$SSOT_DB"; fi
  rm -f "$CONTRACT" "$CALLER"
  if [[ "$BENCH" == "$PROJECT_ROOT/benchmarks/general_repeat_caller/v0.1.0" ]]; then rm -rf "$BENCH"; fi
  if [[ "$QC_DIR" == "$PROJECT_ROOT/qc/12_general_repeat_caller_bootstrap/v0.1.0" ]]; then rm -rf "$QC_DIR"; fi
  exit "$rc"
}
trap cleanup_fail ERR

CONTRACT_PATH="$CONTRACT" CALLER_PATH="$CALLER" SELFTEST_PATH="$SELFTEST" python - <<'PYDECODE'
from pathlib import Path
import base64, os
payloads={
    Path(os.environ['CONTRACT_PATH']): '',
    Path(os.environ['CALLER_PATH']): '',
    Path(os.environ['SELFTEST_PATH']): '',
}
for path,data in payloads.items():
    tmp=path.with_name('.'+path.name+'.part')
    tmp.write_bytes(base64.b64decode(data))
    tmp.chmod(0o755 if path.suffix=='.py' else 0o644)
    tmp.replace(path)
PYDECODE

python -m py_compile "$CALLER" "$SELFTEST"
python "$SELFTEST" --caller "$CALLER" --outdir "$BENCH"

gzip -t "$TARGET_EVIDENCE"
python - "$TARGET_EVIDENCE" "$BENCH/real_p01_regression_seed.tsv" <<'PYREAL'
import csv,gzip,sys
from pathlib import Path
src=Path(sys.argv[1]); out=Path(sys.argv[2])
with gzip.open(src,'rt',encoding='utf-8',newline='') as fh:
    rd=csv.DictReader(fh,delimiter='\t')
    fields=rd.fieldnames or []
    required=['projection_id','read_id','representative_locus_id','canonical_motif','motif_length_bp','evidence_class','sizing_status','repeat_bp_estimate']
    miss=[x for x in required if x not in fields]
    if miss: raise SystemExit('ERROR: target evidence missing fields: '+','.join(miss))
    optional=[x for x in ['purity','confidence_label','best_mapq','target_source','region_type'] if x in fields]
    buckets={k:[] for k in ['1','2','3','4_6','7_10','11_20','gt20']}
    def bucket(v):
        try:n=int(float(v))
        except:return None
        if n==1:return '1'
        if n==2:return '2'
        if n==3:return '3'
        if n<=6:return '4_6'
        if n<=10:return '7_10'
        if n<=20:return '11_20'
        return 'gt20'
    for row in rd:
        if row.get('evidence_class')!='SPAN' or row.get('sizing_status')!='exact_span': continue
        b=bucket(row.get('motif_length_bp',''))
        if b and len(buckets[b])<10: buckets[b].append(row)
        if all(len(v)>=10 for v in buckets.values()): break
selected=[]
for b in ['1','2','3','4_6','7_10','11_20','gt20']:
    for row in buckets[b]:
        row=dict(row); row['motif_length_bin']=b; row['fixture_status']='SEED_MANIFEST_ONLY_RAW_SEQUENCE_MATERIALIZATION_PENDING'; selected.append(row)
if not selected: raise SystemExit('ERROR: no exact-span rows selected')
out_fields=['projection_id','read_id','representative_locus_id','canonical_motif','motif_length_bp','motif_length_bin','evidence_class','sizing_status','repeat_bp_estimate']+optional+['fixture_status']
tmp=out.with_name('.'+out.name+'.part')
with tmp.open('w',newline='',encoding='utf-8') as fh:
    wr=csv.DictWriter(fh,fieldnames=out_fields,delimiter='\t',extrasaction='ignore'); wr.writeheader(); wr.writerows(selected)
tmp.replace(out)
print(f'REAL_REGRESSION_SEED_PASS\trows={len(selected)}\t{out}')
PYREAL

CLI_BAK="$SSOT_CLI.pre_stage12a.$(date +%Y%m%d_%H%M%S).bak"
DB_BAK="$SSOT_DB.pre_stage12a.$(date +%Y%m%d_%H%M%S).bak"
cp -a "$SSOT_CLI" "$CLI_BAK"
cp -a "$SSOT_DB" "$DB_BAK"

python - "$SSOT_CLI" <<'PYSSOT'
from pathlib import Path
import sys,py_compile,hashlib
cli=Path(sys.argv[1]); text=cli.read_text(encoding='utf-8')
marker='# Stage 12A general caller bootstrap v0.1.0'
if marker in text:
    raise SystemExit('ERROR: Stage 12A SSOT patch marker already present')
import re
m=re.search(r'(?m)^TOOL_VERSION\s*=\s*["\']([^"\']+)["\']\s*$', text)
if not m:
    raise SystemExit('ERROR: SSOT TOOL_VERSION declaration not found')
print('SSOT_TOOL_VERSION_DETECTED\t'+m.group(1))
required_snippets=[
    'def add_decision(',
    'def add_interpretation(',
    'def add_contract(',
    'CREATE TABLE open_questions',
    'CREATE TABLE limitations',
]
missing=[x for x in required_snippets if x not in text]
if missing:
    raise SystemExit('ERROR: SSOT structural contract missing: '+', '.join(missing))
anchor='    current_metrics = [\n'
if text.count(anchor)!=1:
    raise SystemExit(f'ERROR: expected exactly one SSOT current_metrics anchor, observed {text.count(anchor)}')
insertion=r'''    # Stage 12A general caller bootstrap v0.1.0
    stage6am_qc = project_root / "qc/11_six_sample_frozen_p01_replay/ENCSR307SHM_pilot100k_mm2splice_v1/rnatr_six_sample_frozen_p01_replay_v0.1.5/six_sample_frozen_p01_replay.qc.tsv"
    stage6am_summary = project_root / "results/11_six_sample_frozen_p01_replay/ENCSR307SHM_pilot100k_mm2splice_v1/rnatr_six_sample_frozen_p01_replay_v0.1.5/six_sample_frozen_p01_replay.summary.tsv"
    stage6am_provenance = project_root / "results/11_six_sample_frozen_p01_replay/ENCSR307SHM_pilot100k_mm2splice_v1/rnatr_six_sample_frozen_p01_replay_v0.1.5/run_stage_provenance.tsv"
    general_contract = project_root / "docs/design/RNA_TR_Scout_general_repeat_caller_contract_v0.1.0.md"
    general_bench = project_root / "benchmarks/general_repeat_caller/v0.1.0"

    conn.execute("UPDATE open_questions SET status='CLOSED', blocking=0, next_action='Completed: six equalized 100k-read fetal-brain datasets replayed through the frozen P0/P1 pipeline; use as engineering validation only.', evidence_path=?, effective_at='2026-08-07T03:03:38+00:00' WHERE question_key='SIX_SAMPLE_REPLAY'", (str(stage6am_qc),))
    conn.execute("UPDATE open_questions SET status='CLOSED', blocking=0, next_action='Architecture contract frozen in v0.1.0; implementation remains a separate blocking task.', evidence_path=?, effective_at='2026-08-07T03:30:00+00:00' WHERE question_key='GENERAL_REPEAT_CALLER_CONTRACT'", (str(general_contract),))
    conn.execute("UPDATE open_questions SET status='OPEN', blocking=0, next_action='DEFER until the general caller is stable and fast enough to process many RNA long-read samples; do not estimate a precise locus/motif technical floor from the six-sample pilot.', evidence_path=?, effective_at='2026-08-07T03:30:00+00:00' WHERE question_key='RNA_TECHNICAL_FLOOR'", (str(stage6am_summary),))

    conn.execute('INSERT OR REPLACE INTO open_questions(question_key,question,priority,status,blocking,next_action,evidence_path,effective_at) VALUES(?,?,?,?,?,?,?,?)', ('GENERAL_REPEAT_CALLER_IMPLEMENTATION','Can the frozen general-caller contract be implemented for compound repeats, interruptions, RNA LPS, de-novo motif rescue, and censored molecules while preserving raw-read/locus-assignment semantics?','CRITICAL','OPEN',1,'Implement compound/interruption segmentation and LPS next, then materialize real P0/P1 raw-sequence regression fixtures and benchmark against the frozen pipeline.',str(general_contract),'2026-08-07T03:30:00+00:00'))
    conn.execute('INSERT OR REPLACE INTO open_questions(question_key,question,priority,status,blocking,next_action,evidence_path,effective_at) VALUES(?,?,?,?,?,?,?,?)', ('PERFORMANCE_OPTIMIZATION_11F_11H','How should production runtime be reduced, especially the computation corresponding to 11f/11h, and where can compiled CPU or GPU batching help?','HIGH','OPEN',0,'Profile after caller semantics stabilize; preserve the CPU/reference implementation as the correctness oracle.',str(stage6am_provenance),'2026-08-07T03:30:00+00:00'))
    conn.execute('INSERT OR REPLACE INTO limitations(limitation_key,statement,severity,status,mitigation,evidence_path,effective_at) VALUES(?,?,?,?,?,?,?)', ('SIX_SAMPLE_PANEL_ENGINEERING_ONLY','The six equalized fetal-brain 100k-read datasets are too small and biologically heterogeneous to define precise locus/motif/length/support-specific RNA technical distributions.','HIGH','ACTIVE','Use them only for engineering robustness and gross-artifact checks. Perform precise RNA background calibration only after the caller is stable/fast and many samples can be processed.',str(stage6am_summary),'2026-08-07T03:30:00+00:00'))
    conn.execute('INSERT OR REPLACE INTO limitations(limitation_key,statement,severity,status,mitigation,evidence_path,effective_at) VALUES(?,?,?,?,?,?,?)', ('CURRENT_RUNTIME_NOT_PRODUCTION_SCALE','The frozen P0/P1 implementation is too slow for routine full-depth cohorts; 11f and 11h are the primary observed hotspots.','HIGH','ACTIVE','Do not optimize prematurely. First stabilize general-caller semantics, then profile duplicate computation, Python overhead, compiled CPU, and GPU batching.',str(stage6am_provenance),'2026-08-07T03:30:00+00:00'))

    add_decision(conn,key='six_sample_scope_engineering_validation',category='development_scope',title='Six-sample panel is engineering validation only',statement='The six 100k-read fetal-brain comparison datasets close the replay/robustness gate but will not be used to estimate a precise RNA technical floor.',status='ACTIVE',confidence='HIGH',rationale='Six samples cannot separate technical variability, biological individual variability, expression/isoform differences, and sparse low-support loci with sufficient precision.',evidence_path=str(stage6am_summary),effective_at='2026-08-07T03:30:00+00:00')
    add_decision(conn,key='general_repeat_caller_contract_v0_1_0',category='algorithm_design',title='General repeat caller contract v0.1.0 frozen',statement='General repeat measurement will re-estimate raw-read repeat boundaries with an error-aware cyclic repeat model, treat catalog motifs as priors, preserve censored semantics, and explicitly support compound/interruption/LPS outputs.',status='ACTIVE',confidence='HIGH',rationale='This separates locus assignment from repeat measurement and provides a stable contract for implementation and benchmarking.',evidence_path=str(general_contract),effective_at='2026-08-07T03:30:00+00:00')
    add_interpretation(conn,key='stage6am_coarse_yield_sanity_only',fact='The target final P0/P1 evidence count and exact-span count fall within the six-sample replay ranges.',interpretation='No gross target-specific pipeline-yield failure is apparent at this coarse engineering level.',do_not='Do not interpret six-sample similarity as a locus-specific normal range, technical floor, pathogenicity result, or personal DNA genotype.',confidence='HIGH',evidence_path=str(stage6am_summary),evidence_metrics={'target_final_rows':49793,'panel_final_min':46160,'panel_final_max':53509,'target_exact_span':23867,'panel_exact_span_min':22114,'panel_exact_span_max':25886},status='ACTIVE',effective_at='2026-08-07T03:30:00+00:00')
    add_contract(conn,key='repeat_definition',name='Repeat definition and sizing',state='CONTRACT_FROZEN_REFERENCE_CORE_PROTOTYPE',statement='General-caller v0.1.0 contract freezes raw-read boundary re-estimation with cyclic error-aware motif alignment; catalog motifs are priors. The reference v0.1.0 single-motif core is implemented, while compound/interruption segmentation, LPS, censored interval inference, and production optimization remain pending.',implementation_id=None,evidence_path=str(general_contract))
    add_contract(conn,key='rna_lps',name='RNA longest pure segment',state='CONTRACT_FROZEN_NOT_IMPLEMENTED',statement='Final caller will keep exact-sequence LPS and error-aware inferred LPS distinct. Neither is complete in reference v0.1.0.',implementation_id=None,evidence_path=str(general_contract))
'''
text=text.replace(anchor,insertion+anchor,1)
tmp=cli.with_name('.'+cli.name+'.stage12a.part')
tmp.write_text(text,encoding='utf-8')
py_compile.compile(str(tmp),doraise=True)
tmp.replace(cli); cli.chmod(0o755)
print('SSOT_SOURCE_PATCH_PASS')
print('ssot_tool_version_preserved\t'+m.group(1))
print('ssot_cli_sha256\t'+hashlib.sha256(cli.read_bytes()).hexdigest())
PYSSOT

python "$SSOT_CLI" --project-root "$PROJECT_ROOT" rebuild
python "$SSOT_CLI" --project-root "$PROJECT_ROOT" validate
trap - ERR

SELF="$(readlink -f "$0")"
if [[ "$SELF" != "$SCRIPT_INSTALL" && ! -e "$SCRIPT_INSTALL" ]]; then
  cp "$SELF" "$SCRIPT_INSTALL.part"; chmod 0755 "$SCRIPT_INSTALL.part"; mv "$SCRIPT_INSTALL.part" "$SCRIPT_INSTALL"
fi

caller_sha="$(sha256sum "$CALLER" | awk '{print $1}')"
contract_sha="$(sha256sum "$CONTRACT" | awk '{print $1}')"
selftest_sha="$(sha256sum "$SELFTEST" | awk '{print $1}')"
synthetic_status="$(awk -F '\t' '$1=="selftest_status"{print $2}' "$BENCH/synthetic_reference_selftest.qc.tsv")"
real_seed_rows="$(($(wc -l < "$BENCH/real_p01_regression_seed.tsv")-1))"
{
  printf 'metric\tvalue\n'
  printf 'stage_version\t%s\n' "$STAGE_VERSION"
  printf 'stage6am_scope\tENGINEERING_VALIDATION_ONLY\n'
  printf 'general_caller_contract\tFROZEN_V0.1.0\n'
  printf 'reference_core\tSINGLE_MOTIF_CYCLIC_ERROR_AWARE_PROTOTYPE\n'
  printf 'synthetic_selftest_status\t%s\n' "$synthetic_status"
  printf 'real_regression_seed_rows\t%s\n' "$real_seed_rows"
  printf 'real_regression_seed_status\tSEED_MANIFEST_ONLY_RAW_SEQUENCE_MATERIALIZATION_PENDING\n'
  printf 'compound_interruption_lps\tNOT_IMPLEMENTED_NEXT\n'
  printf 'rna_technical_floor\tDEFERRED_UNTIL_LARGE_COHORT_AFTER_CALLER_STABILIZATION\n'
  printf 'performance_optimization\tDEFERRED_UNTIL_CALLER_SEMANTICS_STABLE\n'
  printf 'caller_sha256\t%s\n' "$caller_sha"
  printf 'contract_sha256\t%s\n' "$contract_sha"
  printf 'selftest_sha256\t%s\n' "$selftest_sha"
  printf 'next_gate\tIMPLEMENT_COMPOUND_INTERRUPTION_LPS_AND_MATERIALIZE_REAL_REGRESSION_READS\n'
  printf 'audit_status\tPASS\n'
} > "$QC.part"
mv "$QC.part" "$QC"

echo '===== STAGE 12A COMPLETE ====='
cat "$BENCH/synthetic_reference_selftest.qc.tsv"
echo
echo '===== BOOTSTRAP QC ====='
cat "$QC"
echo
echo "Contract: $CONTRACT"
echo "Caller:   $CALLER"
echo "Bench:    $BENCH"
echo "QC:       $QC"
echo 'STAGE12A_PASS'
